def main():
    n, q = map(int, input().split())

    record = [(i, 0) for i in range(1, n+1)]
    direction_map = {"R": (1, 0), "L": (-1, 0), "U": (0, 1), "D": (0, -1)}

    for _ in range(q):
        command = input().split()
        if command[0] == "1":
            C = command[1]
            dx, dy = direction_map[C]
            # Update the head position
            head_x, head_y = record[0]
            new_head_position = (head_x + dx, head_y + dy)
            # Move each part to the position of the part in front of it
            for i in range(n-1, 0, -1):
                record[i] = record[i-1]
            record[0] = new_head_position
        elif command[0] == "2":
            p = int(command[1])
            print(*record[p-1])
